styles.h1:
font-family: "Ma Shan Zheng", "PingFang SC", cursive;
font-size: 28px;
position: relative;
color: rgb(201, 168, 238); /* 文字颜色 */
margin-bottom: 8px;
letter-spacing: 4px;
font-weight: 600;
text-align: center;
z-index: 1;
position: relative;

styles.h2:
font-size: 16px;
color: #333;
margin-bottom: 24px;
font-weight: 600;
text-align: center;
position: relative;
padding-bottom: 10px;

styles.h3:
display: block;
color: #333;
margin-bottom: 6px;
font-size: 16px;
font-weight: 600;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.strong:
font-weight: 600;
text-decoration: underline;
text-decoration-color: #e74c3c;
text-decoration-style: wavy;
text-underline-offset: 4px;

styles.a:
color: #8863cf;
text-decoration: none;
border-bottom: 1px dashed #d5c8f0;
transition: all 0.3s ease;

styles.li:
position: relative;


margin-bottom: 20px;
padding-left: 40px;
color: #333;
font-size: 15px;

styles.hr:
background: linear-gradient(to right, transparent, #8863cf, transparent);
height: 1px;
opacity: 0.5;

